component_data_script:
rows = props.get("reminders") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

reminders = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	while len(parts) < 7:
		parts.append("")
	reminders.append({"label": parts[0], "sender": parts[1], "to": parts[2], "sent": parts[3], "subject": parts[4], "body": parts[5], "action": parts[6]})
for i in range(len(reminders)):
	item = reminders[i]
	item["pressed"] = "true" if i == 0 else "false"
	item["tab"] = "0" if i == 0 else "-1"
	item["on"] = "true" if i == 0 else "false"
	item["hidden"] = "false" if i == 0 else "true"
	item["has_action"] = len(item["action"]) > 0
component.reminders = reminders
component.component_data = {"start": 0}
